					$current_category = get_the_category()[0]->cat_ID;
				    $args = array(
				        'cat'            => $current_category,  
				        'posts_per_page' => 10,
				    );
				    $query = new WP_Query($args);
				    if ($query->have_posts()):
				    	while ($query->have_posts()) : $query->the_post();
					        ?>
					        <li style="color:#fff"><?php the_permalink(); ?></li>
					        <?php endwhile;
				        wp_reset_postdata();
				    else :
